import logging
import json
import cherrypy
import splunk.appserver.mrsparkle.lib.config as config
from splunk.rest import simpleRequest, format
from splunk.telemetry_utils import generate_base_telemetry_payload, check_auth_params

logger = logging.getLogger('splunk.appserver')

def post_telemetry_metric(info, options={}):
    """
    FOR INTERNAL SPLUNK USE ONLY.

    Tries to send a telemetry event to Splunk's servers.

    @type  info: dict
    @param info: A dictionary containing the type (string) of the event and the
                 data (dict), which contains the additional data to go along with
                 the event.

    @type options: dict
    @param options: A dictionary containing information about the options that could be
                    used to send telemetry with (refer to the keys in default_options).
                    If cherrypy is not defined, a valid session_key, app, and owner must be provided within options.

    @rtype: None
    """
    _session_key = options.get('session_key')
    owner = options.get('owner')
    app = options.get('app')
    logger.debug(info)

    try:
        if _session_key is None:
            _session_key = cherrypy.session.get('sessionKey')
            cherrypy_config = config.getConfig(sessionKey=_session_key)
            owner = cherrypy_config.get('USERNAME')
            app = cherrypy_config.get('DEFAULT_NAMESPACE')
        check_auth_params(app, owner, _session_key)
        jsonargs = generate_base_telemetry_payload(info)
    except (ValueError, TypeError) as e:
        logger.warning(e)
        return
    try:
        (response, data) = simpleRequest(
            path='/servicesNS/{}/{}/telemetry-metric'.format(owner, app),
            sessionKey=_session_key,
            method='POST',
            jsonargs=json.dumps(jsonargs)
        )
        logger.debug('Response from /telemetry-metric: {}'.format(response))
        logger.debug('Info sent to /telemetry-metric: {}'.format(data))
    except Exception as e:
        is_session_key_set = _session_key != None and _session_key != ''
        logger.warning('Failed to send telemetry event: {} for {} with the parameters app={} owner={} is_session_key_set={}'.format(e, info, app, owner, is_session_key_set))
